	if err = randomize.Struct(seed, &a, documentoVendaItemDBTypes, false, strmangle.SetComplement(documentoVendaItemPrimaryKeyColumns, documentoVendaItemColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
